    /**
     * @method
     * @name dreamdex#fetchBalance
     * @description query for balance in a specific market vault. DreamDEX uses per-market vaults rather than a single exchange-wide wallet, so params.symbol is required. The API does not distinguish between free and locked (in-order) balances, so all balance is reported as free.
     * @see https://api.dreamdex.io/v0/.well-known/oapi.json
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} params.symbol unified market symbol (required — vault is per-market)
     * @returns {object} a [balance structure]{@link https://docs.ccxt.com/#/?id=balance-structure}
     */
    public async override Task<object> fetchBalance(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.authenticateRest();
        await this.loadMarkets();
        object symbol = this.safeString(parameters, "symbol");
        if (isTrue(isEqual(symbol, null)))
        {
            throw new ArgumentsRequired ((string)add(this.id, " fetchBalance() requires a params.symbol argument (vault is per-market)")) ;
        }
        object market = this.market(symbol);
        object request = new Dictionary<string, object>() {
            { "symbol", getValue(market, "id") },
            { "walletAddress", this.walletAddress },
        };
        parameters = this.omit(parameters, "symbol");
        object response = await this.privateGetV0MarketsSymbolVaultBalance(this.extend(request, parameters));
        //
        //     {
        //         "balances": [
        //             { "currency": "SOMI", "amount": "1000.5" },
        //             { "currency": "USDso", "amount": "500.25" }
        //         ]
        //     }
        //
        object balances = this.safeList(response, "balances", new List<object>() {});
        return this.parseBalance(balances);
    }

    public override object parseBalance(object response)
    {
        object result = new Dictionary<string, object>() {
            { "info", response },
        };
        for (object i = 0; isLessThan(i, getArrayLength(response)); postFixIncrement(ref i))
        {
            object balance = this.safeDict(response, i, new Dictionary<string, object>() {});
            object currencyId = this.safeString(balance, "currency");
            object code = this.safeCurrencyCode(currencyId);
            object account = this.account();
            object total = this.safeString(balance, "amount");
            ((IDictionary<string,object>)account)["total"] = total;
            ((IDictionary<string,object>)account)["free"] = total;
            ((IDictionary<string,object>)result)[(string)code] = account;
        }
        return this.safeBalance(result);
    }

