    public async virtual Task<object> vaultAction(object action, object symbol, object currency, object amount, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.authenticateRest();
        await this.loadMarkets();
        object market = this.market(symbol);
        object walletAddress = this.safeString(parameters, "walletAddress", this.walletAddress);
        parameters = this.omit(parameters, "walletAddress");
        object currencyObj = this.currency(currency);
        object request = new Dictionary<string, object>() {
            { "symbol", getValue(market, "id") },
            { "walletAddress", walletAddress },
            { "currency", getValue(currencyObj, "id") },
            { "amount", this.numberToString(amount) },
        };
        object response = null;
        if (isTrue(isEqual(action, "approve")))
        {
            response = await this.privatePostV0MarketsSymbolVaultApprove(this.extend(request, parameters));
        } else if (isTrue(isEqual(action, "deposit")))
        {
            response = await this.privatePostV0MarketsSymbolVaultDeposit(this.extend(request, parameters));
        } else if (isTrue(isEqual(action, "withdraw")))
        {
            response = await this.privatePostV0MarketsSymbolVaultWithdraw(this.extend(request, parameters));
        }
        //
        //     {
        //         "to": "0xcee4c19f4518A10FBeF92390FE6d9e7B18A4070c",
        //         "data": "0x80702f83...",
        //         "value": "0",
        //         "chainId": "50312",
        //         "gasLimit": "250000",
        //         "nonce": "42"
        //     }
        //
        // The approve endpoint responds with JSON null when no approval is required
        // (e.g. native-token currencies). Normalize to undefined so callers can truthy-check.
        if (isTrue(isEqual(response, null)))
        {
            return null;
        }
        return response;
    }

    /**
     * @method
     * @name dreamdex#createOrder
     * @description creates an order by returning an unsigned EVM transaction for the user to sign and broadcast on-chain.
     * The order is not placed until the transaction is submitted to the Somnia network (chain ID 50312).
     * The returned order structure has the unsigned transaction payload in the info field.
     * @see https://api.dreamdex.io/v0/.well-known/oapi.json
     * @param {string} symbol unified market symbol
     * @param {string} type 'limit' or 'market'
     * @param {string} side 'buy' or 'sell'
     * @param {float} amount how much of currency you want to trade in units of base currency
     * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.walletAddress] the wallet address to place the order from (defaults to this.walletAddress)
     * @param {float} [params.triggerPrice] the price at which a stop order is triggered - routes to the stop-orders endpoint
     * @param {float} [params.stopPrice] alias for triggerPrice
     * @param {string} [params.triggerOperator] 'gte' or 'lte' - trigger condition (default: 'lte' for sell, 'gte' for buy)
     * @param {string} [params.timeInForce] 'IOC', 'FOK', or 'PO' - maps to API orderType (immediateOrCancel, fillOrKill, postOnly)
     * @param {bool} [params.postOnly] true to create a post-only order (alternative to timeInForce 'PO')
     * @param {string} [params.fundingSource] 'wallet' or 'vault' - where to source tokens (default is 'wallet', 'vault' uses pre-deposited balance)
     * @param {string} [params.selfMatchingOption] 'cancelTaker' or 'cancelMaker' - self-trade prevention behavior
     * @returns {object} an [order structure]{@link https://docs.ccxt.com/#/?id=order-structure} with the unsigned EVM transaction in the info field
     */
    public async override Task<object> createOrder(object symbol, object type, object side, object amount, object price = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.authenticateRest();
        await this.loadMarkets();
        object market = this.market(symbol);
        object walletAddress = this.safeString(parameters, "walletAddress", this.walletAddress);
        object triggerPrice = this.safeString2(parameters, "triggerPrice", "stopPrice");
        if (isTrue(!isEqual(triggerPrice, null)))
        {
            object triggerOperator = this.safeString(parameters, "triggerOperator");
            if (isTrue(isEqual(triggerOperator, null)))
            {
                triggerOperator = ((bool) isTrue((isEqual(side, "sell")))) ? "lte" : "gte";
            }
            parameters = this.omit(parameters, new List<object>() {"walletAddress", "triggerPrice", "stopPrice", "triggerOperator"});
            object isMarket = (isEqual(type, "market"));
            if (isTrue(!isTrue(isMarket) && isTrue(isEqual(price, null))))
            {
                throw new ArgumentsRequired ((string)add(this.id, " createOrder() requires a price argument for stop limit orders")) ;
            }
            object stopRequest = new Dictionary<string, object>() {
                { "symbol", getValue(market, "id") },
                { "walletAddress", walletAddress },
                { "type", type },
                { "side", side },
                { "amount", this.amountToPrecision(symbol, amount) },
                { "triggerPrice", this.priceToPrecision(symbol, triggerPrice) },
                { "triggerOperator", triggerOperator },
            };
            if (!isTrue(isMarket))
            {
                ((IDictionary<string,object>)stopRequest)["price"] = this.priceToPrecision(symbol, price);
            }
            object stopResponse = await this.privatePostV0MarketsSymbolStopOrders(this.extend(stopRequest, parameters));
            //
            //     {
            //         "to": "0x1489eA81CBEDd53a8Eb1a95E99AF8EB5683b3330",
            //         "data": "0x...",
            //         "value": "100000000000000000",
            //         "chainId": "50312"
            //     }
            //
            return this.safeOrder(new Dictionary<string, object>() {
                { "id", null },
                { "clientOrderId", null },
                { "timestamp", null },
                { "datetime", null },
                { "lastTradeTimestamp", null },
                { "status", null },
                { "symbol", getValue(market, "symbol") },
                { "type", type },
                { "side", side },
                { "price", price },
                { "amount", amount },
                { "filled", null },
                { "remaining", null },
                { "average", null },
                { "cost", null },
                { "triggerPrice", this.parseNumber(triggerPrice) },
                { "trades", null },
                { "fee", null },
                { "info", stopResponse },
            }, market);
        }
        object fundingSource = this.safeString(parameters, "fundingSource");
        object selfMatchingOption = this.safeString(parameters, "selfMatchingOption");
        parameters = this.omit(parameters, new List<object>() {"walletAddress", "fundingSource", "selfMatchingOption"});
        object isMarketOrder = (isEqual(type, "market"));
        if (isTrue(!isTrue(isMarketOrder) && isTrue(isEqual(price, null))))
        {
            throw new ArgumentsRequired ((string)add(this.id, " createOrder() requires a price argument for limit orders")) ;
        }
        object postOnly = null;
        var postOnlyparametersVariable = this.handlePostOnly(isMarketOrder, false, parameters);
        postOnly = ((IList<object>)postOnlyparametersVariable)[0];
        parameters = ((IList<object>)postOnlyparametersVariable)[1];
        object timeInForce = this.safeStringUpper(parameters, "timeInForce");
        parameters = this.omit(parameters, "timeInForce");
        object request = new Dictionary<string, object>() {
            { "symbol", getValue(market, "id") },
            { "walletAddress", walletAddress },
            { "type", type },
            { "side", side },
            { "amount", this.amountToPrecision(symbol, amount) },
        };
        if (!isTrue(isMarketOrder))
        {
            ((IDictionary<string,object>)request)["price"] = this.priceToPrecision(symbol, price);
        }
        if (isTrue(postOnly))
        {
            ((IDictionary<string,object>)request)["orderType"] = "postOnly";
        } else if (isTrue(isEqual(timeInForce, "IOC")))
        {
            ((IDictionary<string,object>)request)["orderType"] = "immediateOrCancel";
        } else if (isTrue(isEqual(timeInForce, "FOK")))
        {
            ((IDictionary<string,object>)request)["orderType"] = "fillOrKill";
        }
        if (isTrue(!isEqual(fundingSource, null)))
        {
            ((IDictionary<string,object>)request)["fundingSource"] = fundingSource;
        }
        if (isTrue(!isEqual(selfMatchingOption, null)))
        {
            ((IDictionary<string,object>)request)["selfMatchingOption"] = selfMatchingOption;
        }
        object response = await this.privatePostV0MarketsSymbolOrders(this.extend(request, parameters));
        //
        //     {
        //         "chainId": "50312",
        //         "data": "0x80702f83...",
        //         "to": "0xcee4c19f4518A10FBeF92390FE6d9e7B18A4070c",
        //         "value": "0"
        //     }
        //
        return this.safeOrder(new Dictionary<string, object>() {
            { "id", null },
            { "clientOrderId", null },
            { "timestamp", null },
            { "datetime", null },
            { "lastTradeTimestamp", null },
            { "status", null },
            { "symbol", getValue(market, "symbol") },
            { "type", type },
            { "side", side },
            { "price", price },
            { "amount", amount },
            { "filled", null },
            { "remaining", null },
            { "average", null },
            { "cost", null },
            { "trades", null },
            { "fee", null },
            { "info", response },
        }, market);
    }

