    /**
     * @method
     * @name dreamdex#fetchOrders
     * @description fetches a list of orders placed by the user
     * @see https://api.dreamdex.io/v0/.well-known/oapi.json
     * @param {string} [symbol] unified market symbol; when omitted returns orders across all markets
     * @param {int} [since] timestamp in ms of the earliest order to retrieve
     * @param {int} [limit] the maximum number of orders to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.status] order status to filter by: 'open', 'closed', 'canceled', 'expired', 'rejected' (or 'pending', 'triggered', 'canceled', 'failed' for stop orders)
     * @param {bool} [params.stop] set to true to fetch stop orders instead of regular orders (requires symbol)
     * @param {bool} [params.trigger] alias for params.stop
     * @returns {Order[]} a list of [order structures]{@link https://docs.ccxt.com/#/?id=order-structure}
     */
    public async override Task<object> fetchOrders(object symbol = null, object since = null, object limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.authenticateRest();
        await this.loadMarkets();
        object stop = this.safeBool2(parameters, "stop", "trigger");
        if (isTrue(isEqual(symbol, null)))
        {
            if (isTrue(stop))
            {
                throw new ArgumentsRequired ((string)add(this.id, " fetchOrders() requires a symbol argument for stop orders")) ;
            }
            object allResponse = await this.privateGetV0Orders(parameters);
            object allOrders = this.safeList(allResponse, "orders", new List<object>() {});
            return this.parseOrders(allOrders, null, since, limit);
        }
        object market = this.market(symbol);
        object request = new Dictionary<string, object>() {
            { "symbol", getValue(market, "id") },
        };
        if (isTrue(stop))
        {
            parameters = this.omit(parameters, new List<object>() {"stop", "trigger"});
            object stopResponse = await this.privateGetV0MarketsSymbolStopOrders(this.extend(request, parameters));
            object stopOrders = this.safeList(stopResponse, "stopOrders", new List<object>() {});
            return this.parseOrders(stopOrders, market, since, limit);
        }
        object response = await this.privateGetV0MarketsSymbolOrders(this.extend(request, parameters));
        object orders = this.safeList(response, "orders", new List<object>() {});
        return this.parseOrders(orders, market, since, limit);
    }

