    /**
     * @method
     * @name dreamdex#cancelOrder
     * @description cancels an open order
     * @see https://api.dreamdex.io/v0/.well-known/oapi.json
     * @param {string} id order id
     * @param {string} symbol unified market symbol, required for dreamdex
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {bool} [params.stop] set to true to cancel a stop order (returns unsigned EVM transaction)
     * @param {bool} [params.trigger] alias for params.stop
     * @returns {object} an [order structure]{@link https://docs.ccxt.com/#/?id=order-structure}
     */
    public async override Task<object> cancelOrder(object id, object symbol = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if (isTrue(isEqual(symbol, null)))
        {
            throw new ArgumentsRequired ((string)add(this.id, " cancelOrder() requires a symbol argument")) ;
        }
        await this.authenticateRest();
        await this.loadMarkets();
        object market = this.market(symbol);
        object stop = this.safeBool2(parameters, "stop", "trigger");
        object request = new Dictionary<string, object>() {
            { "symbol", getValue(market, "id") },
            { "id", id },
        };
        if (isTrue(stop))
        {
            parameters = this.omit(parameters, new List<object>() {"stop", "trigger"});
            object stopResponse = await this.privateDeleteV0MarketsSymbolStopOrdersId(this.extend(request, parameters));
            // stop order cancel returns unsigned EVM transaction, not an order object
            return this.safeOrder(new Dictionary<string, object>() {
                { "id", id },
                { "clientOrderId", null },
                { "timestamp", null },
                { "datetime", null },
                { "lastTradeTimestamp", null },
                { "status", null },
                { "symbol", getValue(market, "symbol") },
                { "type", null },
                { "side", null },
                { "price", null },
                { "amount", null },
                { "filled", null },
                { "remaining", null },
                { "average", null },
                { "cost", null },
                { "trades", null },
                { "fee", null },
                { "info", stopResponse },
            }, market);
