        object rawTriggerPrice = this.safeString(order, "triggerPrice");
        if (isTrue(!isEqual(rawTriggerPrice, null)))
        {
            return this.parseStopOrder(order, market);
        }
        //
        //     {
        //         "id": "01KC1F8N2NBP5GEYKE66CRJ34A",
        //         "status": "open",
        //         "createdAt": 1765534169841,
        //         "symbol": "SOMI:USDso",
        //         "type": "limit",
        //         "side": "buy",
        //         "price": "1.25",
        //         "amount": "500",
        //         "filled": "150",
        //         "remaining": "350",
        //         "walletAddress": "0x1234...",
        //         "txHash": "0xabc..."
        //     }
        //
        object marketId = this.safeString(order, "symbol");
        market = this.safeMarket(marketId, market, ":");
        object timestamp = this.safeInteger(order, "createdAt");
        object price = this.safeNumber(order, "price");
        return this.safeOrder(new Dictionary<string, object>() {
            { "id", this.safeString(order, "id") },
            { "clientOrderId", null },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", null },
            { "status", this.parseOrderStatus(this.safeString(order, "status")) },
            { "symbol", getValue(market, "symbol") },
            { "type", this.safeString(order, "type") },
            { "side", this.safeString(order, "side") },
            { "price", price },
            { "amount", this.safeNumber(order, "amount") },
            { "filled", this.safeNumber(order, "filled") },
            { "remaining", this.safeNumber(order, "remaining") },
            { "average", price },
            { "cost", null },
            { "trades", null },
            { "fee", null },
            { "info", order },
        }, market);
    }

