    public virtual object hashMessage(object message)
    {
        object binaryMessage = this.encode(message);
        object binaryMessageLength = this.binaryLength(binaryMessage);
        object x19 = this.base16ToBinary("19");
        object newline = this.base16ToBinary("0a");
        object prefix = this.binaryConcat(x19, this.encode("Ethereum Signed Message:"), newline, this.encode(this.numberToString(binaryMessageLength))); // eslint-disable-line quotes
        return add("0x", this.hash(this.binaryConcat(prefix, binaryMessage), keccak, "hex"));
    }

    public virtual object signHash(object hash, object privateKey)
    {
        this.checkRequiredCredentials();
        object signature = ecdsa(slice(hash, -64, null), slice(privateKey, -64, null), secp256k1, null);
        object r = getValue(signature, "r");
        object s = getValue(signature, "s");
        object v = this.intToBase16(this.sum(27, getValue(signature, "v")));
        return add(add(add("0x", (r as String).PadLeft(Convert.ToInt32(64), Convert.ToChar("0"))), (s as String).PadLeft(Convert.ToInt32(64), Convert.ToChar("0"))), v);
    }

    public async virtual Task<object> authenticateRest(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        object cachedToken = this.safeString(this.options, "authToken");
        object cachedExpires = this.safeInteger(this.options, "authTokenExpires");
        object now = this.milliseconds();
        if (isTrue(isTrue(isTrue((!isEqual(cachedToken, null))) && isTrue((!isEqual(cachedExpires, null)))) && isTrue((isLessThan(now, cachedExpires)))))
        {
            return cachedToken;
        }
        object nonceResponse = await this.publicGetV0AuthNonce(parameters);
        object nonce = this.safeString(nonceResponse, "nonce");
        object issuedAt = this.iso8601(now);
        object url = this.safeString(getValue(this.urls, "api"), "rest");
        object message = add(add(add(add(add(add(add(add(add(add(add(add(add(add(add(add(add(add(add(add(url, " wants you to sign in with your Ethereum account:"), "\n"), this.walletAddress), "\n"), "\n"), "Sign in to Somnia DEX"), "\n"), "\n"), "URI: "), url), "\n"), "Version: 1"), "\n"), "Chain ID: 50312"), "\n"), "Nonce: "), nonce), "\n"), "Issued At: "), issuedAt); // eslint-disable-line quotes
        object hash = this.hashMessage(message);
        object sig = this.signHash(hash, this.privateKey);
        object loginRequest = new Dictionary<string, object>() {
            { "message", message },
            { "signature", sig },
        };
        object loginResponse = await this.publicPostV0AuthLogin(loginRequest);
        //
        //     { "token": "eyJhbGciOi...", "expiresAt": 1765537769841 }
        //
        object token = this.safeString(loginResponse, "token");
        object expiresAt = this.safeInteger(loginResponse, "expiresAt");
        ((IDictionary<string,object>)this.options)["authToken"] = token;
        ((IDictionary<string,object>)this.options)["authTokenExpires"] = expiresAt;
        return token;
    }

    public override object sign(object path, object api = null, object method = null, object parameters = null, object headers = null, object body = null)
    {
        api ??= "public";
        method ??= "GET";
        parameters ??= new Dictionary<string, object>();
        object url = add(add(this.safeString(getValue(this.urls, "api"), "rest"), "/"), this.implodeParams(path, parameters));
        object query = this.omit(parameters, this.extractParams(path));
        if (isTrue(isEqual(api, "private")))
        {
            object token = this.safeString(this.options, "authToken");
            headers = new Dictionary<string, object>() {
                { "Authorization", add("Bearer ", token) },
            };
            if (isTrue(isTrue((isEqual(method, "POST"))) || isTrue((isEqual(method, "PATCH")))))
            {
                ((IDictionary<string,object>)headers)["Content-Type"] = "application/json";
                body = this.json(query);
            } else
            {
                if (isTrue(getArrayLength(new List<object>(((IDictionary<string,object>)query).Keys))))
                {
                    url = add(url, add("?", this.urlencode(query)));
                }
            }
        } else
        {
            if (isTrue(isEqual(method, "POST")))
            {
                headers = new Dictionary<string, object>() {
                    { "Content-Type", "application/json" },
                };
                body = this.json(query);
            } else
            {
                if (isTrue(getArrayLength(new List<object>(((IDictionary<string,object>)query).Keys))))
                {
                    url = add(url, add("?", this.urlencode(query)));
                }
            }
        }
        return new Dictionary<string, object>() {
            { "url", url },
            { "method", method },
            { "body", body },
            { "headers", headers },
        };
    }

    public override object handleErrors(object httpCode, object reason, object url, object method, object headers, object body, object response, object requestHeaders, object requestBody)
    {
        if (isTrue(isEqual(response, null)))
        {
            return null;
        }
        object errorName = this.safeString(response, "name");
        if (isTrue(!isEqual(errorName, null)))
        {
            object feedback = add(add(this.id, " "), body);
            this.throwExactlyMatchedException(getValue(this.exceptions, "exact"), errorName, feedback);
            this.throwBroadlyMatchedException(getValue(this.exceptions, "broad"), body, feedback);
            if (isTrue(isGreaterThanOrEqual(httpCode, 400)))
            {
                throw new ExchangeError ((string)feedback) ;
            }
        }
        return null;
    }
